#include <iostream>
#include <vector>

using namespace std;

int L, C, P;
int grid[7][7]; // 1 se tem peça preta, 0 caso contrário
bool candidate[7][7];

int dx[] = {-1, 1, 0, 0};
int dy[] = {0, 0, -1, 1};

bool isValid(int r, int c) {
    return r >= 1 && r <= L && c >= 1 && c <= C;
}

vector<int> adj[40];
int match_to[40];
bool visited[40];

bool dfs(int u) {
    for (int v : adj[u]) {
        if (visited[v]) continue;
        visited[v] = true;
        if (match_to[v] < 0 || dfs(match_to[v])) {
            match_to[v] = u;
            return true;
        }
    }
    return false;
}

int main() {
    ios_base::sync_with_stdio(false);
    cin.tie(NULL);

    if (!(cin >> L >> C)) return 0;
    cin >> P;
    for (int i = 0; i < P; ++i) {
        int r, c;
        cin >> r >> c;
        grid[r][c] = 1;
    }

    int total_candidates = 0;
    for (int r = 1; r <= L; ++r) {
        for (int c = 1; c <= C; ++c) {
            if (grid[r][c] == 1) continue;
            bool has_black_neighbor = false;
            for (int d = 0; d < 4; ++d) {
                int nr = r + dx[d];
                int nc = c + dy[d];
                if (isValid(nr, nc) && grid[nr][nc] == 1) {
                    has_black_neighbor = true;
                    break;
                }
            }
            if (has_black_neighbor) {
                candidate[r][c] = true;
                total_candidates++;
            }
        }
    }

    auto get_id = [&](int r, int c) {
        return (r - 1) * C + (c - 1);
    };

    for (int r = 1; r <= L; ++r) {
        for (int c = 1; c <= C; ++c) {
            if (!candidate[r][c]) continue;
            // Partição 1: (r + c) % 2 == 0
            if ((r + c) % 2 == 0) {
                int u = get_id(r, c);
                for (int d = 0; d < 4; ++d) {
                    int nr = r + dx[d];
                    int nc = c + dy[d];
                    if (isValid(nr, nc) && candidate[nr][nc]) {
                        int v = get_id(nr, nc);
                        adj[u].push_back(v);
                    }
                }
            }
        }
    }

    for (int i = 0; i < L * C; ++i) {
        match_to[i] = -1;
    }

    int max_matching = 0;
    for (int r = 1; r <= L; ++r) {
        for (int c = 1; c <= C; ++c) {
            if (candidate[r][c] && (r + c) % 2 == 0) {
                int u = get_id(r, c);
                for (int i = 0; i < L * C; ++i) visited[i] = false;
                if (dfs(u)) {
                    max_matching++;
                }
            }
        }
    }

    int max_independent_set = total_candidates - max_matching;
    cout << max_independent_set << "\n";

    return 0;
}
